+			}
+			b = &d->bufcache[slot];
+			b->block = block;
+			b->full = true;
+			b->next = -1;
+			b->prev = d->mru;
+			if (d->mru >= 0)
+				d->bufcache[d->mru].next = slot;
+			else
+				d->lru = slot;
+			d->mru = slot;
+			starthd_in(d, &vetti[i * DIM_BLOCK], block, 1);
+			sem_wait(d->sincr);
+			memcpy(b->buf, &vetti[i * DIM_BLOCK], DIM_BLOCK);
+		}
+	}
+	sem_signal(d->mutex);

